CREATE OR ALTER PROCEDURE [dbo].[uspUserRole_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @UserGroupId UNIQUEIDENTIFIER = NULL
	, @ObjectMenuId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[UserGroupId]
			, t.[ObjectMenuId]
			, t.[AllowAccess]
			, t.[AllowAdd]
			, t.[AllowEdit]
			, t.[AllowDelete]
			, t.[AllowPrint]
			, t.[AllowExport]
			, t.[AllowImport]
			, t.[CreatedDate]
		FROM [dbo].[UserRole] AS t
		
		WHERE 1 = 1
			AND (@UserGroupId IS NULL OR t.[UserGroupId] = @UserGroupId)
			AND (@ObjectMenuId IS NULL OR t.[ObjectMenuId] = @ObjectMenuId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'userGroupId' THEN r.[UserGroupId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'userGroupId' THEN r.[UserGroupId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'objectMenuId' THEN r.[ObjectMenuId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'objectMenuId' THEN r.[ObjectMenuId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'allowAccess' THEN r.[AllowAccess] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'allowAccess' THEN r.[AllowAccess] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'allowAdd' THEN r.[AllowAdd] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'allowAdd' THEN r.[AllowAdd] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'allowEdit' THEN r.[AllowEdit] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'allowEdit' THEN r.[AllowEdit] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'allowDelete' THEN r.[AllowDelete] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'allowDelete' THEN r.[AllowDelete] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'allowPrint' THEN r.[AllowPrint] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'allowPrint' THEN r.[AllowPrint] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'allowExport' THEN r.[AllowExport] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'allowExport' THEN r.[AllowExport] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'allowImport' THEN r.[AllowImport] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'allowImport' THEN r.[AllowImport] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
